sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    /*
     * POST /eval/generate
     *
     * Body:
     *   task_description   string  required  What the prompt is meant to accomplish.
     *   prompt_inputs_spec object  required  { "key": "description", ... } of template inputs.
     *   num_cases          number  optional  Number of test cases to generate (default 3).
     *
     * Response:
     *   { dataset_id, case_count, task_description }
     */

    var body = request.body.data;
    var taskDescription  = (body.task_description   || '').toString().trim();
    var promptInputsSpec = body.prompt_inputs_spec  || {};
    var numCases         = parseInt(body.num_cases  || 3, 10);

    if (!taskDescription) {
        response.setStatus(400);
        response.setBody({ error: 'task_description is required.' });
        return;
    }
    if (typeof promptInputsSpec !== 'object') {
        response.setStatus(400);
        response.setBody({ error: 'prompt_inputs_spec must be a JSON object.' });
        return;
    }
    if (isNaN(numCases) || numCases < 1) { numCases = 3; }
    if (numCases > 10)                   { numCases = 10; }

    var evaluator = new x_146833_claudec_0.ClaudePromptEvaluator();
    var datasetId = evaluator.generateDataset(taskDescription, promptInputsSpec, numCases);

    response.setStatus(200);
    response.setBody({
        dataset_id:       datasetId,
        case_count:       numCases,
        task_description: taskDescription
    });

})(request, response);
